import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 16;
constexpr int TM = 8;
constexpr int TN = 8;
constexpr int LDAK = BK + 4;   // As stored [BM][BK] row-major for 16B cp.async
constexpr int LDB = BN + 4;    // Bs stored [BK][BN]
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ < 800)
#define SGEMM_HAS_CP_ASYNC 0
#else
#define SGEMM_HAS_CP_ASYNC 1
#endif
__device__ __forceinline__ void cp_async16(void* smem_dst, const void* gmem_src, int src_bytes)
{
#if SGEMM_HAS_CP_ASYNC
    const unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16, %2;\n"
                 :: "r"(dst), "l"(gmem_src), "r"(src_bytes));
#else
    float* d = reinterpret_cast<float*>(smem_dst);
    const float* s = reinterpret_cast<const float*>(gmem_src);
    const int nf = src_bytes >> 2;
    #pragma unroll
    for (int i = 0; i < 4; ++i) d[i] = (i < nf) ? s[i] : 0.0f;
#endif
}
__device__ __forceinline__ void cp_async_commit()
{
#if SGEMM_HAS_CP_ASYNC
    asm volatile("cp.async.commit_group;\n");
#endif
}
template <int NG>
__device__ __forceinline__ void cp_async_wait()
{
#if SGEMM_HAS_CP_ASYNC
    asm volatile("cp.async.wait_group %0;\n" :: "n"(NG));
#endif
}
__device__ __forceinline__ void load_ab_tile(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ As,
    float* __restrict__ Bs,
    int N, int k0, int bx, int by, int tid, bool vec_ok)
{
    if (vec_ok) {
        // A tile: BM x BK via 16-byte cp.async into row-major As[ml][kl]
        #pragma unroll
        for (int r = 0; r < 2; ++r) {
            const int idx = tid + r * 256;      // 0..511
            const int ml = idx >> 2;            // 0..127
            const int kl = (idx & 3) * 4;       // 0,4,8,12
            const int gm = by * BM + ml;
            const int gk = k0 + kl;
            const int gm_c = (gm < N) ? gm : (N - 1);
            const int gk_c = (gk < N) ? gk : (N - 4);
            int bytes = 0;
            if (gm < N && gk < N) {
                const int rem = N - gk;
                bytes = (rem >= 4) ? 16 : (rem * 4);
            }
            cp_async16(As + ml * LDAK + kl, A + (long long)gm_c * N + gk_c, bytes);
        }
        // B tile: BK x BN via 16-byte cp.async into Bs[kl][nl]
        #pragma unroll
        for (int r = 0; r < 2; ++r) {
            const int idx = tid + r * 256;      // 0..511
            const int kl = idx >> 5;            // 0..15
            const int nl = (idx & 31) * 4;      // 0..124
            const int gk = k0 + kl;
            const int gn = bx * BN + nl;
            const int gk_c = (gk < N) ? gk : (N - 1);
            const int gn_c = (gn < N) ? gn : (N - 4);
            int bytes = 0;
            if (gk < N && gn < N) {
                const int rem = N - gn;
                bytes = (rem >= 4) ? 16 : (rem * 4);
            }
            cp_async16(Bs + kl * LDB + nl, B + (long long)gk_c * N + gn_c, bytes);
        }
    } else {
        // Scalar fallback for N not divisible by 4 (unaligned rows)
        #pragma unroll
        for (int r = 0; r < 2; ++r) {
            const int idx = tid + r * 256;
            const int ml = idx >> 2;
            const int kl = (idx & 3) * 4;
            const int gm = by * BM + ml;
            const int gk = k0 + kl;
            float v0 = 0.0f, v1 = 0.0f, v2 = 0.0f, v3 = 0.0f;
            if (gm < N) {
                if (gk + 0 < N) v0 = A[(long long)gm * N + gk + 0];
                if (gk + 1 < N) v1 = A[(long long)gm * N + gk + 1];
                if (gk + 2 < N) v2 = A[(long long)gm * N + gk + 2];
                if (gk + 3 < N) v3 = A[(long long)gm * N + gk + 3];
            }
            As[ml * LDAK + kl + 0] = v0;
            As[ml * LDAK + kl + 1] = v1;
            As[ml * LDAK + kl + 2] = v2;
            As[ml * LDAK + kl + 3] = v3;
        }
        #pragma unroll
        for (int r = 0; r < 2; ++r) {
            const int idx = tid + r * 256;
            const int kl = idx >> 5;
            const int nl = (idx & 31) * 4;
            const int gk = k0 + kl;
            const int gn = bx * BN + nl;
            float v0 = 0.0f, v1 = 0.0f, v2 = 0.0f, v3 = 0.0f;
            if (gk < N) {
                if (gn + 0 < N) v0 = B[(long long)gk * N + gn + 0];
                if (gn + 1 < N) v1 = B[(long long)gk * N + gn + 1];
                if (gn + 2 < N) v2 = B[(long long)gk * N + gn + 2];
                if (gn + 3 < N) v3 = B[(long long)gk * N + gn + 3];
            }
            Bs[kl * LDB + nl + 0] = v0;
            Bs[kl * LDB + nl + 1] = v1;
            Bs[kl * LDB + nl + 2] = v2;
            Bs[kl * LDB + nl + 3] = v3;
        }
    }
}
__global__ __launch_bounds__(256, 2) void sgemm_square_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N)
{
    __shared__ float As[2][BM * LDAK];
    __shared__ float Bs[2][BK * LDB];
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;  // 0..15
    const int ty = threadIdx.y;  // 0..15
    const int tid = ty * 16 + tx;
    const int m0 = by * BM + ty;
    const int n0 = bx * BN + tx;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    const bool vec_ok = ((N & 3) == 0);
    const int numTiles = (N + BK - 1) / BK;
    // Prologue: asynchronously load K-tile 0 into stage 0.
    load_ab_tile(A, B, As[0], Bs[0], N, 0, bx, by, tid, vec_ok);
    cp_async_commit();
    int stage = 0;
    for (int t = 0; t < numTiles; ++t) {
        if (t + 1 < numTiles) {
            // Prefetch next K-tile into the other buffer while computing current one.
            load_ab_tile(A, B, As[stage ^ 1], Bs[stage ^ 1], N, (t + 1) * BK, bx, by, tid, vec_ok);
            cp_async_commit();
            cp_async_wait<1>();
        } else {
            cp_async_wait<0>();
        }
        __syncthreads();
        const float* Asc = As[stage];
        const float* Bsc = Bs[stage];
        #pragma unroll
        for (int k = 0; k < BK; ++k) {
            float a[TM];
            float b[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                a[i] = Asc[(ty + i * 16) * LDAK + k];
            }
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                b[j] = Bsc[k * LDB + tx + j * 16];
            }
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    acc[i][j] = fmaf(a[i], b[j], acc[i][j]);
                }
            }
        }
        __syncthreads();
        stage ^= 1;
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int gm = m0 + i * 16;
        if (gm < N) {
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                const int gn = n0 + j * 16;
                if (gn < N) {
                    C[(long long)gm * N + gn] = acc[i][j];
                }
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must have the same N");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "A and B must be contiguous");

    const int N = static_cast<int>(A.size(0));
    auto C = torch::empty_like(A);

    dim3 block(16, 16);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    sgemm_square_kernel<<<grid, block, 0, stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

_ext = load_inline(
    name="modelnew_square_matmul_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matmul_cuda"],
    extra_cflags=["-O3", "-std=c++17"],
    extra_cuda_cflags=["-O3", "-std=c++17", "--use_fast_math"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using one custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _ext.matmul_cuda(A, B)

